import requests, numpy as np, collections
import matplotlib.pyplot as plt
H={"User-Agent":"openscientist/1.0 (research)"}
txt=requests.get("https://files.rcsb.org/download/8OUZ.pdb",headers=H,timeout=60).text
prot=collections.defaultdict(list); lig=collections.defaultdict(list)
for ln in txt.splitlines():
    if ln.startswith(("ATOM","HETATM")):
        if ln[76:78].strip()=="H": continue
        ch=ln[21]; resi=int(ln[22:26]); rn=ln[17:20].strip()
        xyz=np.array([float(ln[30:38]),float(ln[38:46]),float(ln[46:54])])
        if ln.startswith("ATOM"): prot[(ch,resi,rn)].append(xyz)
        elif rn in ("ATP","ADP"): lig[(ch,resi,rn)].append(xyz)
prot={k:np.array(v) for k,v in prot.items()}; lig={k:np.array(v) for k,v in lig.items()}
nm={"A":"RAD51B","B":"RAD51C","C":"RAD51D","D":"XRCC2"}
col={"RAD51B":"#8c8c8c","RAD51C":"#4c72b0","RAD51D":"#c44e52","XRCC2":"#55a868"}
def mind(a,b): return float(np.sqrt(((a[:,None,:]-b[None,:,:])**2).sum(-1)).min())

site_labels=[]; site_counts=[]
for k,v in sorted(lig.items()):
    c=collections.Counter()
    for pk,pv in prot.items():
        if mind(v,pv)<4.5: c[nm[pk[0]]]+=1
    site_labels.append(f"{k[2]} bound by\n{nm[k[0]]}"); site_counts.append(c)

fig,ax=plt.subplots(1,2,figsize=(12.5,4.8))
bot=np.zeros(len(site_labels))
for s in ["RAD51B","RAD51C","RAD51D","XRCC2"]:
    vals=np.array([c.get(s,0) for c in site_counts],dtype=float)
    ax[0].bar(site_labels,vals,bottom=bot,color=col[s],label=s,edgecolor="white")
    for i,(v,b) in enumerate(zip(vals,bot)):
        if v: ax[0].text(i,b+v/2,f"{s}\n{int(v)}",ha="center",va="center",fontsize=8,color="white",weight="bold")
    bot+=vals
ax[0].set_ylabel("residues within 4.5 A of the nucleotide")
ax[0].set_title("A. Two of the three nucleotide sites in BCDX2 are composite,\nand RAD51D lines both",fontsize=10.5)
ax[0].legend(fontsize=8,frameon=False,ncol=2)

s207=prot[("C",207,"SER")]
env=[]
for pk,pv in prot.items():
    if pk[0]=="C" and abs(pk[1]-207)<=1: continue
    d=mind(s207,pv)
    if d<7.0: env.append((d,nm[pk[0]],pk[2]+str(pk[1])))
for k,v in lig.items():
    d=mind(s207,v)
    if d<7.0: env.append((d,"ligand",f"{k[2]} of {nm[k[0]]}"))
env=sorted(env)[:14][::-1]
ax[1].barh([e[2] for e in env],[e[0] for e in env],color=[col.get(e[1],"#dd8452") for e in env])
ax[1].axvline(4.0,ls="--",color="k",lw=.9)
xr2=mind(s207,np.vstack([v for k,v in prot.items() if k[0]=="D"]))
ax[1].axvline(xr2,ls=":",color="#2d6b3f",lw=1.8)
ax[1].text(xr2-0.3,0.3,f"nearest XRCC2 atom {xr2:.1f} A",rotation=90,ha="right",va="bottom",fontsize=8,color="#2d6b3f")
ax[1].set_xlabel("minimum heavy-atom distance from RAD51D Ser207 (A)"); ax[1].set_xlim(0,19)
ax[1].set_title("B. Ser207, the only pathogenic RAD51D missense, is buried in the RAD51D\ncore beside its own ATP, far from XRCC2",fontsize=10.5)
plt.tight_layout(); plt.show()
